import { Group, Mesh, Shape, ShapeGeometry, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, vec3, uniform, positionWorld, normalWorld, cameraPosition, dot, pow, smoothstep, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const paperColor = new Color('#e8ecf2');
  const accentColor = new Color('#ff2a38');

  // Rounded rectangle geometry (capsule shape)
  const w = 1.2, h = 0.35, r = 0.1;
  const shape = new Shape();
  shape.moveTo(-w/2 + r, -h/2);
  shape.lineTo(w/2 - r, -h/2);
  shape.quadraticCurveTo(w/2, -h/2, w/2, -h/2 + r);
  shape.lineTo(w/2, h/2 - r);
  shape.quadraticCurveTo(w/2, h/2, w/2 - r, h/2);
  shape.lineTo(-w/2 + r, h/2);
  shape.quadraticCurveTo(-w/2, h/2, -w/2, h/2 - r);
  shape.lineTo(-w/2, -h/2 + r);
  shape.quadraticCurveTo(-w/2, -h/2, -w/2 + r, -h/2);
  const geometry = new ShapeGeometry(shape);

  // Material with accent edge light (Fresnel rim)
  const material = new MeshStandardNodeMaterial();
  material.colorNode = vec3(paperColor);
  material.metalnessNode = uniform(1.0);
  material.roughnessNode = uniform(0.35);
  material.transparent = true;

  // Rim emissive using world position and normal
  const viewDir = normalize(positionWorld.xyz.sub(cameraPosition));
  const rim = pow(1.0 - dot(viewDir, normalWorld), 2.5);
  const rimGlow = mix(vec3(0), vec3(accentColor), smoothstep(0.5, 0.85, rim));
  material.emissiveNode = rimGlow;
  material.emissiveIntensity = uniform(1.2);

  // Load ceramic grain texture and set as map
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.mapNode = texture(tex);
    material.mapNode.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0); // group will be positioned by adapter
  group.add(mesh);

  // --- Interactions ---
  const tweens = [];

  // Hover: rise-in (subtle y offset)
  function onPointerEnter() {
    gsap.to(mesh.position, {
      y: 0.15,
      duration: 0.4,
      ease: 'power2.out',
      overwrite: 'auto'
    });
  }

  function onPointerLeave() {
    gsap.to(mesh.position, {
      y: 0,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: 'auto'
    });
  }

  function onClick() {
    // Add press-down effect
    gsap.timeline()
      .to(mesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
      .to(mesh.scale, { x: 1.0, y: 1.0, duration: 0.2, ease: 'power4.out' });
    // Emit collection select event
    if (ctx.emit) ctx.emit('hub-collection.select');
  }

  mesh.userData.handlers = {
    pointerover: onPointerEnter,
    pointerout: onPointerLeave,
    click: onClick
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tweens.forEach(t => t.kill());
    geometry.dispose();
    material.dispose();
    // Texture will be disposed by loader cache
  };

  return group;
}
